const formulario = document.querySelector("#formulario");
const feed = document.querySelector("#feed");
const resenha = document.querySelector("#resenha");
const filtro = document.querySelector("#filtro");
const ordem = document.querySelector("#ordem");

let notaAtual = 0;

const avaliacoes = [];

function atualizarEstrelas() {

  document.querySelectorAll(".estrelas button").forEach(botao => {

      const ativo = Number(botao.dataset.nota) <= notaAtual;

          botao.classList.toggle("ativa", ativo);

              botao.setAttribute("aria-pressed", String(ativo));

                });

                  document.querySelector("#nota-texto").textContent =
                      notaAtual
                            ? notaAtual + " de 5 estrelas"
                                  : "Selecione uma nota";

                                  }

                                  document.querySelectorAll(".estrelas button").forEach(botao => {

                                    botao.onclick = () => {

                                        notaAtual = Number(botao.dataset.nota);

                                            atualizarEstrelas();

                                              };

                                              });

                                              function atualizarEstatisticas() {

                                                const minhas = avaliacoes.filter(item => item.proprio);

                                                  document.querySelector("#minhas-avaliacoes").textContent =
                                                      minhas.length;

                                                        const soma = minhas.reduce(
                                                            (total, item) => total + item.nota,
                                                                0
                                                                  );

                                                                    document.querySelector("#media").textContent =
                                                                        minhas.length
                                                                              ? (soma / minhas.length).toFixed(1)
                                                                                    : "—";

                                                                                    }

                                                                                    function renderizar() {

                                                                                      feed.replaceChildren();

                                                                                        const lista = avaliacoes.filter(item => {

                                                                                            return filtro.value === "Todos" ||
                                                                                                  item.genero === filtro.value;

                                                                                                    });

                                                                                                      if (ordem.value === "melhores") {

                                                                                                          lista.sort((a, b) => b.nota - a.nota);

                                                                                                            }

                                                                                                              document.querySelector("#total").textContent =
                                                                                                                  lista.length + " avaliações";

                                                                                                                    document.querySelector("#vazio").hidden =
                                                                                                                        lista.length > 0;

                                                                                                                          lista.forEach(item => {

                                                                                                                              const post = document.createElement("article");

                                                                                                                                  post.className = "post";

                                                                                                                                      post.innerHTML = `
                                                                                                                                            <div class="autor">

                                                                                                                                                    <div class="avatar"></div>

                                                                                                                                                            <div>
                                                                                                                                                                      <strong class="nome"></strong>
                                                                                                                                                                                <small>CineClub • Avaliação</small>
                                                                                                                                                                                        </div>

                                                                                                                                                                                              </div>

                                                                                                                                                                                                    <div class="filme-info">

                                                                                                                                                                                                            <div class="icone-filme">🎬</div>

                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                              <h3 class="filme"></h3>
                                                                                                                                                                                                                                        <span class="tag"></span>
                                                                                                                                                                                                                                                  <div class="nota"></div>
                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                      <p class="resenha"></p>

                                                                                                                                                                                                                                                                            <div class="acoes">

                                                                                                                                                                                                                                                                                    <button class="curtir">♡ Curtir</button>
                                                                                                                                                                                                                                                                                            <button class="comentar">💬 Comentar</button>

                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                        <div class="comentarios"></div>

                                                                                                                                                                                                                                                                                                              <form class="comentario-form" hidden>

                                                                                                                                                                                                                                                                                                                      <input placeholder="Escreva um comentário..."
                                                                                                                                                                                                                                                                                                                                     maxlength="180"
                                                                                                                                                                                                                                                                                                                                                    required>

                                                                                                                                                                                                                                                                                                                                                            <button type="submit">Enviar</button>

                                                                                                                                                                                                                                                                                                                                                                  </form>
                                                                                                                                                                                                                                                                                                                                                                      `;

                                                                                                                                                                                                                                                                                                                                                                          post.querySelector(".avatar").textContent =
                                                                                                                                                                                                                                                                                                                                                                                item.nome.substring(0, 2).toUpperCase();

                                                                                                                                                                                                                                                                                                                                                                                    post.querySelector(".nome").textContent =
                                                                                                                                                                                                                                                                                                                                                                                          item.nome;

                                                                                                                                                                                                                                                                                                                                                                                              post.querySelector(".filme").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                    item.filme;

                                                                                                                                                                                                                                                                                                                                                                                                        post.querySelector(".tag").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                              item.genero;

                                                                                                                                                                                                                                                                                                                                                                                                                  post.querySelector(".nota").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                        "★".repeat(item.nota) +
                                                                                                                                                                                                                                                                                                                                                                                                                              "☆".repeat(5 - item.nota);

                                                                                                                                                                                                                                                                                                                                                                                                                                  post.querySelector(".resenha").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                        item.texto;

                                                                                                                                                                                                                                                                                                                                                                                                                                            const curtir = post.querySelector(".curtir");

                                                                                                                                                                                                                                                                                                                                                                                                                                                function atualizarCurtida() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                      curtir.textContent = item.curtido
                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? "♥ " + (item.likes + 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : "♡ " + item.likes;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            curtir.classList.toggle("ativo", item.curtido);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    curtir.onclick = () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          item.curtido = !item.curtido;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                atualizarCurtida();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const formComentario =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              post.querySelector(".comentario-form");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  post.querySelector(".comentar").onclick = () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        formComentario.hidden = !formComentario.hidden;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!formComentario.hidden) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      formComentario.querySelector("input").focus();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function mostrarComentarios() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const area = post.querySelector(".comentarios");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                area.replaceChildren();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      item.comentarios.forEach(texto => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const comentario = document.createElement("p");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      comentario.textContent = "Ewerthon: " + texto;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              area.append(comentario);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formComentario.onsubmit = evento => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  evento.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const campo = formComentario.querySelector("input");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const texto = campo.value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!texto) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          item.comentarios.push(texto);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarComentarios();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      formComentario.reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (item.proprio) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const excluir = document.createElement("button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          excluir.textContent = "Excluir";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                excluir.className = "excluir";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      excluir.onclick = () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              avaliacoes.splice(avaliacoes.indexOf(item), 1);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      renderizar();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  post.querySelector(".acoes").append(excluir);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          atualizarCurtida();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              mostrarComentarios();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  feed.append(post);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      atualizarEstatisticas();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function adicionarAvaliacao(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        nome,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          filme,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            genero,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              nota,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                texto,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  proprio,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    likes = 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      avaliacoes.unshift({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          nome,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              filme,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  genero,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      nota,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          texto,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              proprio,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  likes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      curtido: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          comentarios: []
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              renderizar();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              resenha.oninput = () => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.querySelector("#contador").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    resenha.value.length + "/350";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    formulario.onsubmit = evento => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      evento.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const filme = document.querySelector("#filme").value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const genero = document.querySelector("#genero").value;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const texto = resenha.value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const aviso = document.querySelector("#aviso");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!filme || !texto || notaAtual === 0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    aviso.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "Preencha os campos e selecione uma avaliação.";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  filtro.value = "Todos";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ordem.value = "recentes";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      adicionarAvaliacao(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "Ewerthon",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              filme,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  genero,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      notaAtual,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          texto,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  formulario.reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    notaAtual = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      atualizarEstrelas();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.querySelector("#contador").textContent = "0/350";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          aviso.textContent = "Avaliação publicada com sucesso!";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          filtro.onchange = renderizar;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ordem.onchange = renderizar;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          adicionarAvaliacao(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "CineClub",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "Interestelar",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Ficção científica",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Uma história que combina exploração espacial, ciência e emoção.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        34
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        adicionarAvaliacao(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "Cinema Brasil",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Como Treinar o Seu Dragão",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "Animação",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "Uma aventura sobre amizade, coragem e superação.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      21
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      adicionarAvaliacao(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Ewerthon",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "Homem-Aranha no Aranhaverso",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Animação",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              4,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Uma animação com identidade visual criativa e uma narrativa envolvente.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    18
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarEstrelas();